// Original, deterministic local PCM. No network service or third-party samples.
const drums=['Kick','Snare','Clap','Closed Hat','Open Hat','Low Tom','Mid Tom','High Tom','Crash','Shaker','Cowbell','Rim','Bass','Laser','Zap','Chime'];
const instruments=['Warm Keys','Glass Bell','Soft Pluck','Round Bass','Reed Organ','Air Flute','Bright Lead','Dream Strings'];
export const SOUND_LIBRARY=[...['Neon','Punch','Cosmic'].flatMap((kit,bank)=>drums.map((name,type)=>({id:`builtin-${bank}-${type}`,name:`${name} · ${kit}`,category:'Drums & kits',bank,type}))),...instruments.flatMap((name,instrument)=>[130.8128,261.6256,523.2511].map((frequency,octave)=>({id:`library-tone-${instrument}-${octave}`,name:`${name} · C${octave+3}`,category:'Melodic instruments',instrument,frequency}))),...['Rising Spark','Falling Star','Bubble Pop','Space Sweep','Soft Noise','Robot Chirp','Arcade Coin','Deep Pulse'].map((name,effect)=>({id:`library-effect-${effect}`,name,category:'Effects & textures',effect}))];
export function findSounds(query='',category='all'){const q=query.toLowerCase().trim();return SOUND_LIBRARY.filter(s=>(category==='all'||s.category===category)&&`${s.name} ${s.category}`.toLowerCase().includes(q));}
export function libraryPCM(sound,sr=44100){if(sound.instrument===undefined&&sound.effect===undefined)throw Error('Kit sounds use the existing drum synthesizer.');const duration=sound.instrument===undefined?.8:1.5,data=new Float32Array(Math.ceil(duration*sr));let phase=0,seed=27031995;
for(let i=0;i<data.length;i++){const t=i/sr,u=t/duration;seed=(Math.imul(seed,1664525)+1013904223)>>>0;const noise=seed/2147483648-1;let value=0,f=sound.frequency||220;if(sound.instrument!==undefined){phase+=2*Math.PI*f/sr;const sine=Math.sin(phase),harm=Math.sin(phase*2),soft=Math.tanh(2*sine);switch(sound.instrument){case 0:value=(sine+.25*harm)*Math.exp(-t*3);break;case 1:value=(sine+.35*Math.sin(phase*2.76))*Math.exp(-t*5);break;case 2:value=(sine+.3*Math.sin(phase*3))*Math.exp(-t*8);break;case 3:value=(sine+.12*harm)*Math.exp(-t*2);break;case 4:value=(sine+.3*Math.sin(phase*3)+.15*Math.sin(phase*5));break;case 5:value=(sine+.1*harm+.03*noise)*Math.min(1,t*12);break;case 6:value=soft*.8;break;case 7:value=(sine+.4*Math.sin(phase*1.004)+.2*harm)*Math.min(1,t*8);break;}}else{f=[300+1800*u,1800-1500*u,220+650*Math.exp(-t*25),120+2200*u*u,0,350+250*Math.sin(t*32),t<.12?660:990,65+40*Math.exp(-t*18)][sound.effect];phase+=2*Math.PI*f/sr;value=(sound.effect===4?noise*.5:Math.sin(phase))*Math.exp(-t*(sound.effect===2?10:3));}const envelope=Math.min(1,t*200)*Math.min(1,(duration-t)*20);data[i]=Math.max(-.95,Math.min(.95,value*.42*envelope));}return data;}
